<?php
if (!defined('ABSPATH')) exit;
/** Administrator-only catalogue workspace. Discovery reads local store data, never executes page content. */
class DXPS_Feed_Editor {
 private static function input($key,$label,$value,$help='',$type='text') {
  echo '<label class="dxf-field" for="dxf-'.esc_attr($key).'"><span>'.esc_html($label).'</span><input type="'.esc_attr($type).'" id="dxf-'.esc_attr($key).'" name="'.esc_attr($key).'" value="'.esc_attr($value).'">';
  if($help)echo '<small>'.esc_html($help).'</small>';echo '</label>';
 }
 private static function select($key,$label,$value,$options) {
  echo '<label class="dxf-field" for="dxf-'.esc_attr($key).'"><span>'.esc_html($label).'</span><select id="dxf-'.esc_attr($key).'" name="'.esc_attr($key).'">';
  foreach($options as $k=>$v)echo '<option value="'.esc_attr($k).'" '.selected($k,$value,false).'>'.esc_html($v).'</option>';echo '</select></label>';
 }
 private static function check($key,$label,$value) {echo '<label class="dxf-check"><input type="checkbox" name="'.esc_attr($key).'" value="1" '.checked(!empty($value),true,false).'> '.esc_html($label).'</label>';}
 private static function form($id) {echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="dxps_feed"><input type="hidden" name="id" value="'.esc_attr($id).'">';wp_nonce_field('dxps_feed');}
 private static function section($id,$title,$help='') {echo '<section class="dxf-card" id="dxf-section-'.esc_attr($id).'"><h3>'.esc_html($title).'</h3>';if($help)echo '<p class="description">'.esc_html($help).'</p>';}
 public static function progress() {
  if(!current_user_can('manage_options'))wp_send_json_error(array('message'=>'Not authorized.'),403);
  check_ajax_referer('dxps_feed_progress','nonce');$id=sanitize_key(wp_unslash($_POST['id']??''));
  if(!DXPS_Feeds::config($id))wp_send_json_error(array('message'=>'Feed not found.'),404);
  $s=DXPS_Feeds::status($id);if('running'===($s['state']??'')&&!empty($s['run']))DXPS_Feeds::batch($id,$s['run']);
  $s=DXPS_Feeds::status($id);wp_send_json_success(array_intersect_key($s,array_flip(array('state','processed','rows','skipped','errors','warnings','failure'))));
 }
 public static function render($id,$cfg) {
  $c=array_merge(DXPS_Feed_Options::DEFAULTS,$cfg);$d=DXPS_Feed_Options::discover();
  $terms=get_terms(array('taxonomy'=>'product_cat','hide_empty'=>false));if(is_wp_error($terms))$terms=array();
  // A single locally published candidate can populate an otherwise empty URL. Merchant account labels are never invented.
  foreach(array('shipping'=>'shipping_policy_url','returns'=>'return_policy_url') as $flag=>$key){$pages=array_values(array_filter($d['pages'],function($p)use($flag){return $p[$flag];}));if(!$c[$key]&&1===count($pages))$c[$key]=$pages[0]['url'];}
  echo '<div class="dxf-workspace"><h2>'.($id?'Edit feed':'Create a feed').'</h2><nav class="dxf-nav" aria-label="Feed settings">';
  foreach(array('basics'=>'Setup','categories'=>'Categories & identifiers','shipping'=>'Shipping & returns','filters'=>'Products','mapping'=>'Field mappings','preview'=>'Preview & issues') as $k=>$v)echo '<a href="#dxf-section-'.esc_attr($k).'">'.esc_html($v).'</a>';echo '</nav>';
  self::form($id);
  self::section('basics','Feed setup');echo '<div class="dxf-grid">';
  self::input('name','Feed name',$c['name']);self::select('platform','Platform',$c['platform'],DXPS_Feeds::PROFILES);
  self::select('format','File format',$c['format'],array('xml'=>'XML (RSS 2.0)','tsv'=>'TSV / tab-separated text','csv'=>'CSV','json'=>'JSON (generic only)'));
  self::select('schedule','Refresh schedule',$c['schedule'],array('hourly'=>'Hourly','twicedaily'=>'Twice daily','daily'=>'Daily','manual'=>'Manual'));
  self::select('tax_mode','Product price tax treatment',$c['tax_mode'],array('display'=>'Match WooCommerce shop display','including'=>'Including tax','excluding'=>'Excluding tax'));
  self::select('condition','Fallback condition',$c['condition'],array('new'=>'New','used'=>'Used','refurbished'=>'Refurbished'));echo '</div></section>';
  self::section('categories','Categories & manufacturer identifiers','These controls address the missing category and identifier warnings. Never invent GTINs or use a shop SKU as the manufacturer MPN.');echo '<div class="dxf-grid">';
  self::input('brand','Fallback manufacturer brand',$c['brand'],'Used only when the product has no brand.');
  self::input('google_category','Fallback Google category',$c['google_category'],'Google taxonomy ID or full category path.');
  self::select('identifier_mode','Identifier policy',$c['identifier_mode'],array('preserve'=>'Use product data; warn when incomplete','required'=>'Exclude offers without GTIN or brand + MPN','none'=>'No manufacturer identifiers assigned (confirm below)'));echo '</div>';
  self::check('identifier_confirmed','I confirm that products lacking identifiers were not assigned a GTIN or MPN by the manufacturer. Existing identifiers remain in use.',$c['identifier_confirmed']);
  echo '<details open><summary>Map WooCommerce categories to Google categories</summary><p>Product-specific categories take priority. For products in several mapped categories, the most specific category wins, then the lowest term ID.</p><p><button class="button" type="button" data-dxf-presets>Suggest hair-shop categories</button> Suggestions: wigs → 181; extensions, ponytails and toppers → 4057. Review before saving.</p><div class="dxf-table"><table class="widefat striped"><thead><tr><th>Store category</th><th>Google taxonomy ID or path</th></tr></thead><tbody>';
  foreach($terms as $t)echo '<tr><td><label for="dxf-cat-'.(int)$t->term_id.'">'.esc_html($t->name).' <small>#'.(int)$t->term_id.'</small></label></td><td><input id="dxf-cat-'.(int)$t->term_id.'" data-category-name="'.esc_attr($t->name).'" name="category_map['.(int)$t->term_id.']" value="'.esc_attr($c['category_map'][$t->term_id]??'').'" placeholder="e.g. 181"></td></tr>';
  echo '</tbody></table></div></details></section>';
  self::section('shipping','Shipping & return policies','DX scans published store pages and enabled WooCommerce shipping methods. Policy text is evidence; conditional checkout rates and exceptions need review.');
  echo '<div class="dxf-discovery"><h4>Found in your store</h4><p>'.(int)$d['scanned'].' published pages checked (up to 1,000, plus configured policy pages). '.count($d['pages']).' policy candidates and '.count($d['shipping']).' enabled shipping methods found.</p>';
  if(!$d['pages'])echo '<p>No matching published policy page found. Publish a shipping/returns page, then use Scan store again below. DX does not create business terms from missing information.</p>';
  foreach($d['pages'] as $page){echo '<details><summary>'.esc_html($page['title']).'</summary><p><a href="'.esc_url($page['url']).'" target="_blank" rel="noopener noreferrer">Open source page</a></p><blockquote>'.esc_html($page['text']).'</blockquote>';
   foreach(array('shipping_policy_url'=>'Use as shipping policy','return_policy_url'=>'Use as return policy') as $target=>$label)echo '<button type="button" class="button" data-policy-target="'.esc_attr($target).'" data-policy-url="'.esc_attr($page['url']).'">'.esc_html($label).'</button> ';echo '</details>';}
  foreach($d['shipping'] as $rate){echo '<details><summary>'.esc_html($rate['zone'].' · '.$rate['title']).'</summary><p>'.esc_html(implode(', ',$rate['locations'])?:'Rest of the world / zone fallback').'</p><p>'.esc_html('Method: '.$rate['method'].'; cost: '.($rate['cost']===''?'not set':$rate['cost']).'; tax status: '.$rate['tax_status']).'</p>';
   if($rate['requires']||$rate['min_amount'])echo '<p>'.esc_html('Free-shipping condition: '.$rate['requires'].'; threshold: '.$rate['min_amount'].' '.get_woocommerce_currency()).'</p>';
   echo '<p>Zone order, shipping classes, coupons, destination tax and cart quantities can change checkout rates. Only use a flat rate below when it applies to every included product at the stated destination.</p>';
   if(!empty($rate['import']))echo '<button class="button" type="button" data-shipping-import="'.esc_attr(wp_json_encode($rate['import'])).'">Copy country flat rate to editor</button>';echo '</details>';}
  echo '</div><div class="dxf-grid">';self::input('shipping_policy_url','Shipping policy URL',$c['shipping_policy_url'],'A discovered single matching page is filled automatically.','url');self::input('return_policy_url','Return policy URL',$c['return_policy_url'],'Keep the same policy URL in your merchant account.','url');
  self::select('shipping_mode','Shipping rates source',$c['shipping_mode'],array('account'=>'Use shipping configured in the platform account','manual'=>'Include explicit destination rates in this feed'));echo '</div>';
  echo '<div data-shipping-fields><p>Rates are in '.esc_html(get_woocommerce_currency()).' and must match checkout, including applicable shipping tax. A blank region covers the selected country. Delivery days are Google/generic fields. Do not enter a free rate for a conditional free-shipping threshold.</p><div class="dxf-table"><table class="widefat"><thead><tr>';
  foreach(array('Country','Region / state','Service','Price','Handling min','Handling max','Transit min','Transit max') as $h)echo '<th>'.esc_html($h).'</th>';echo '</tr></thead><tbody>';
  $countries=WC()->countries->get_countries();$count=max(5,count($c['shipping_rows'])+1);$count=min(20,$count);
  for($i=0;$i<$count;$i++){$rate=$c['shipping_rows'][$i]??array();echo '<tr data-shipping-row><td><select aria-label="Destination country '.($i+1).'" name="shipping_rows['.$i.'][country]"><option value="">Choose…</option>';foreach($countries as $code=>$name)echo '<option value="'.esc_attr($code).'" '.selected($rate['country']??'',$code,false).'>'.esc_html($name).'</option>';echo '</select></td>';
   foreach(array('region','service','price','min_handling_time','max_handling_time','min_transit_time','max_transit_time') as $key){$value=$rate[$key]??'';if('price'===$key&&$value!=='')$value=explode(' ',$value)[0];echo '<td><input aria-label="'.esc_attr(str_replace('_',' ',$key).' '.($i+1)).'" name="shipping_rows['.$i.']['.esc_attr($key).']" value="'.esc_attr($value).'"'.(in_array($key,array('region','service'),true)?'':' inputmode="decimal"').'></td>'; }echo '</tr>';}
  echo '</tbody></table></div><p>Save to reveal another row (maximum 20). Clear country and price together to remove a row.</p></div><div class="dxf-grid">';self::input('return_policy_label','Google return policy label',$c['return_policy_label'],'Optional exact label of a policy already created in Merchant Center. This does not create or upload the policy.');echo '</div>';
  self::check('return_policy_confirmed','This label and any product-specific return labels are already configured in Google Merchant Center.',$c['return_policy_confirmed']);
  echo '<p>For Google, configure return window, return fees, methods, countries and exceptions in Merchant Center → Shipping and returns. Meta and other platforms manage returns in their own account settings. Policy URLs are saved here for setup; they are not emitted as unsupported feed attributes.</p></section>';
  self::section('filters','Product selection & content');echo '<div class="dxf-grid">';
  foreach(array('include_categories'=>'Include categories (empty = all)','exclude_categories'=>'Exclude categories') as $key=>$label){echo '<label class="dxf-field"><span>'.esc_html($label).'</span><select multiple size="6" name="'.esc_attr($key).'[]">';foreach($terms as $t)echo '<option value="'.(int)$t->term_id.'" '.selected(in_array($t->term_id,$c[$key]),true,false).'>'.esc_html($t->name).'</option>';echo '</select><small>Ctrl / Command + click selects or clears several categories.</small></label>';}
  self::input('exclude_ids','Exclude product IDs',implode(',',$c['exclude_ids']),'Comma-separated IDs.');self::input('min_price','Minimum displayed price',$c['min_price']);self::input('max_price','Maximum displayed price',$c['max_price']);
  self::input('title_prefix','Title prefix',$c['title_prefix']);self::input('title_suffix','Title suffix',$c['title_suffix']);self::select('description_source','Description source',$c['description_source'],array('full'=>'Full product description','short'=>'Short description when available'));self::input('image_limit','Maximum additional images (0–10)',$c['image_limit'],'Main image is always retained.','number');
  self::select('backorder_mode','Backorders without an availability date',$c['backorder_mode'],array('strict'=>'Exclude the offer and report it','estimate'=>'Publish as backorder, available in the number of days below','in_stock'=>'Publish as in stock','out_of_stock'=>'Publish as out of stock'));
  self::input('backorder_days','Backorder lead time (days)',$c['backorder_days'],'Your real delivery lead time for backordered products. Used only with the estimate option.','number');
  self::input('link_params','Tracking parameters for product links',$c['link_params'],'Optional, e.g. utm_source=google&utm_medium=shopping&utm_campaign=catalogue. {id} inserts the product ID.');
  self::input('price_tiers','Price tiers for automatic labels',implode(', ',(array)$c['price_tiers']),'Upper limits in '.get_woocommerce_currency().', used by the automatic custom labels below.');echo '</div>';
  foreach(array('include_children'=>'Include descendants when matching category filters','in_stock_only'=>'Exclude out-of-stock products','sale_only'=>'Only products currently on sale','exclude_virtual'=>'Exclude virtual products','auto_labels'=>'Fill empty custom labels automatically: 0 price tier, 1 sale state, 2 sales history, 3 new arrival, 4 stock level (for campaign structure and bidding)','apparel'=>'Require apparel fields: color, size, gender and age group') as $k=>$label)self::check($k,$label,$c[$k]);echo '</section>';
  self::section('mapping','Field mappings','Choose a source without writing JSON. Automatic uses WooCommerce and DX product fields. A nonempty explicit mapping overrides automatic values.');
  echo '<details><summary>Configure attribute, taxonomy, custom field or fixed-value mappings</summary><div class="dxf-table"><table class="widefat striped"><thead><tr><th>Feed field</th><th>Source</th><th>Key or value</th></tr></thead><tbody>';
  foreach(DXPS_Feed_Product::MAPPABLE as $field){list($type,$key)=array_pad(explode(':',$c['mapping'][$field]??'',2),2,'');echo '<tr><th>'.esc_html($field).'</th><td><select aria-label="'.esc_attr($field).' source" name="mapping_rows['.esc_attr($field).'][type]">';foreach(array(''=>'Automatic','meta'=>'Product custom field','attribute'=>'Product attribute','taxonomy'=>'Product taxonomy','literal'=>'Fixed value') as $v=>$label)echo '<option value="'.esc_attr($v).'" '.selected($type,$v,false).'>'.esc_html($label).'</option>';echo '</select></td><td><input aria-label="'.esc_attr($field).' key or value" name="mapping_rows['.esc_attr($field).'][key]" value="'.esc_attr($key).'" placeholder="e.g. pa_color, product_brand, _global_unique_id"></td></tr>';}
  echo '</tbody></table></div></details></section><div class="dxf-actions"><button class="button button-primary button-hero" name="op" value="save">Save feed</button> <a class="button" href="'.esc_url(admin_url('admin.php?page=dx-pixel-suite&tab=feeds')).'">New feed</a><span>Save, then select Build above to publish these settings.</span></div></form>';
  self::form($id);echo '<p><button class="button" name="op" value="discover">Scan store again</button> Discovery is cached for 15 minutes. Save your edits before scanning.</p></form>';
  self::section('preview','Product preview & actionable issues','The browser message “This XML file does not appear to have any style information” is normal for a machine-readable feed. It is not a feed error.');
  if($id){echo '<form method="get"><input type="hidden" name="page" value="dx-pixel-suite"><input type="hidden" name="tab" value="feeds"><input type="hidden" name="edit" value="'.esc_attr($id).'">';self::input('preview_id','Preview a product or variation ID',absint($_GET['preview_id']??0)?:'','Uses saved settings.','number');echo '<button class="button">Preview product</button></form>';
   $pid=absint($_GET['preview_id']??0);if($pid){$r=DXPS_Feed_Product::build(wc_get_product($pid),$c);if(isset($r['skip']))echo '<p>Excluded: '.esc_html($r['skip']).'</p>';else{echo '<div class="dxf-table"><table class="widefat striped"><tbody>';foreach($r['row'] as $key=>$value)if(''!==$value&&array()!==$value)echo '<tr><th>'.esc_html($key).'</th><td>'.esc_html(is_array($value)?wp_json_encode($value,JSON_UNESCAPED_UNICODE):$value).'</td></tr>';echo '</tbody></table></div>';foreach(array_merge($r['errors'],$r['warnings']) as $code)echo '<p>'.esc_html(DXPS_Feed_Options::issue($code)).'</p>';}}
   $s=DXPS_Feeds::status($id);$counts=$s['issue_counts']??array();if(!$counts)foreach($s['issues']??array() as $issue)$counts[$issue['code']]=($counts[$issue['code']]??0)+1;
   if($counts){echo '<h4>What to fix</h4><table class="widefat striped"><thead><tr><th>Occurrences</th><th>Resolution</th></tr></thead><tbody>';foreach($counts as $code=>$count)echo '<tr><td>'.(int)$count.'</td><td>'.esc_html(DXPS_Feed_Options::issue($code)).'</td></tr>';echo '</tbody></table>';}
   if(!empty($s['issues'])){echo '<details><summary>Product issue samples (up to 100)</summary><table class="widefat striped"><thead><tr><th>Product</th><th>Severity</th><th>Issue</th></tr></thead><tbody>';foreach($s['issues'] as $issue){$p=wc_get_product($issue['product_id']);$edit_id=$p&&$p->is_type('variation')?$p->get_parent_id():$issue['product_id'];echo '<tr><td><a href="'.esc_url(get_edit_post_link($edit_id)).'">'.(int)$issue['product_id'].'</a></td><td>'.esc_html($issue['severity']).'</td><td>'.esc_html(DXPS_Feed_Options::issue($issue['code'])).'</td></tr>';}echo '</tbody></table></details>';}
  }else echo '<p>Save the feed to preview a product and build its validation report.</p>';
  echo '</section></div>';
 }
}
